using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using NUnit.Framework;
using UnityEngine;
using UnityEditor.SceneManagement;
namespace SporeGobbo.Geometry.Preview.Tests
{
 public sealed class Stage51Tests
 {
  static Vector2 V(Point2 p)=>new Vector2((float)p.X,(float)p.Y);
  static bool Clear(EnvironmentState s,Point2 p,float size=1)=>PreviewMotion.Fits(s.World,V(p),size);
  static void Open(EnvironmentState s){Assert.That(s.World.Excavate(s.Region.X+32,s.Region.Y-18));s.OnExcavation();}
  [Test] public void ProtectedFootprintIsIrregularCrossesChunksAndRejectsAllExcavation(){var s=new EnvironmentState();var keys=new HashSet<DualTile>();int count=0;for(int y=480;y<540;y++)for(int x=480;x<550;x++)if(s.Region.Protected(x,y)){count++;keys.Add(StreamingCoordinates.Owner(x,y));Assert.That(s.World.IsSolid(x,y));Assert.That(s.World.Excavate(x,y),Is.False);}Assert.That(count,Is.GreaterThan(100));Assert.That(keys.Count,Is.GreaterThanOrEqualTo(4));Assert.That(s.World.EditCount,Is.Zero);}
  [Test] public void AuthoredDefinitionDoesNotChangeDefaultWorld(){var a=new StreamingWorld(1024,1024);var b=new EnvironmentState().World;for(int y=10;y<1000;y+=17)for(int x=10;x<1000;x+=19)if(!b.Definition.TrySolid(x,y,out _)&&!b.Definition.Protected(x,y))Assert.That(b.IsSolid(x,y),Is.EqualTo(a.IsSolid(x,y)));}
  [Test] public void ProtectedDirtBoundaryUsesCanonicalMeshWithDeterministicWindingAndBounds()
  {
   var s=new EnvironmentState();Assert.That(s.World.Excavate(523,506));var cache=new ContourTerrainCache(s.World);var a=PreviewMeshBuilder.BuildPatch(s.World,cache,512,496,16);var b=PreviewMeshBuilder.BuildPatch(s.World,new ContourTerrainCache(s.World),512,496,16);
   for(int k=0;k<a.Length;k++){Assert.That(a[k].Vertices,Is.EqualTo(b[k].Vertices));Assert.That(a[k].Indices,Is.EqualTo(b[k].Indices));for(int i=0;i<a[k].Indices.Count;i+=3){var p=a[k].Vertices[a[k].Indices[i]];var q=a[k].Vertices[a[k].Indices[i+1]];var r=a[k].Vertices[a[k].Indices[i+2]];Assert.That(Vector3.Cross(q-p,r-p).z,Is.LessThan(0));}foreach(var v in a[k].LogicalVertices){Assert.That(v.Logical.X,Is.InRange(511,530));Assert.That(v.Logical.Y,Is.InRange(495,514));}}
  }
  [Test] public void PreexistingRoomIsOpenYetSealedAndUndiscovered(){var s=new EnvironmentState();Assert.That(Clear(s,s.Region.Chamber));Assert.That(s.Discovered,Is.False);Assert.That(s.OnExcavation(),Is.False);Assert.That(s.Discovered,Is.False);Assert.That(s.DiscoveryVisits,Is.LessThanOrEqualTo(8239));}
  [TestCase(true)][TestCase(false)]public void ActualBreakthroughDiscoversWithoutWaitingForVisualTransition(bool gradual){var s=new EnvironmentState{Gradual=gradual};Assert.That(s.World.Excavate(s.Region.X+32,s.Region.Y-18));Assert.That(s.OnExcavation());Assert.That(s.Discovered);Assert.That(Clear(s,s.Region.Seal));Assert.That(s.Reveal,Is.EqualTo(gradual?0:1));s.Step(.7);Assert.That(s.Reveal,Is.EqualTo(1));Assert.That(s.OnExcavation(),Is.False);}
  [Test] public void DiscoveryDoesNotAffectClearanceAndVisibleIsDistinct(){var s=new EnvironmentState();bool before=Clear(s,s.Region.Chamber,7);Assert.That(s.CurrentlyVisible(s.Region.Chamber),Is.False);Open(s);Assert.That(Clear(s,s.Region.Chamber,7),Is.EqualTo(before));Assert.That(s.CurrentlyVisible(s.Region.Entry),Is.False);Assert.That(s.CurrentlyVisible(s.Region.Chamber));}
  [Test] public void LocalDigChangesActualNavigationConnectivity(){var s=new EnvironmentState();var r=new List<Point2>();var before=new LabNavigation(s.World,s.Region.Entry);before.Route(s.Region.Chamber,1,r);Assert.That(r.Any(p=>s.Region.InRoom(p)),Is.False);Open(s);var after=new LabNavigation(s.World,s.Region.Entry);Assert.That(after.Route(s.Region.Chamber,1,r));Assert.That(r.Any(p=>s.Region.InRoom(p)));foreach(var p in r)Assert.That(Clear(s,p));}
  [TestCase(1)][TestCase(3)][TestCase(7)][TestCase(9)]public void CoverNeverOwnsCollisionOrActorAnchors(int size){var s=new EnvironmentState();var p=s.Region.P(-18,23);bool fits=Clear(s,p,size);Assert.That(s.Region.UnderCover(p));foreach(bool cut in new[]{false,true}){EnvironmentState.CoverOpacity(p,p,cut,1);Assert.That(Clear(s,p,size),Is.EqualTo(fits));var d=new PreviewMeshData("actor",PreviewLayer.Gobbo);Stage50Preview.BuildSilhouette(d,p,size,3);d.VisualActorAnchor=p;Assert.That(d.VisualActorAnchor.Value,Is.EqualTo(p));}if(size<=7)Assert.That(fits);else Assert.That(fits,Is.False);}
  [Test] public void CutawayIsLocalAndIndependentOfDiscovery(){var p=new Point2(1,1);Assert.That(EnvironmentState.CoverOpacity(p,p,true,1),Is.EqualTo(.15f).Within(1e-6));Assert.That(EnvironmentState.CoverOpacity(p,p,false,1),Is.EqualTo(1));Assert.That(EnvironmentState.CoverOpacity(new Point2(20,20),p,true,1),Is.EqualTo(1));}
  [Test]public void CoveredEntranceOnlyBecomesConnectedAfterExcavation(){var s=new EnvironmentState();Assert.That(s.World.IsSolid(s.Region.X-32,s.Region.Y+23));Assert.That(Clear(s,s.Region.P(-18,23)));s.World.Excavate(s.Region.X-32,s.Region.Y+23);s.OnExcavation();Assert.That(s.CoverOpened);Assert.That(Clear(s,s.Region.P(-32,23)));Assert.That(s.Region.UnderCover(s.Region.P(-18,23)));Assert.That(s.Discovered,Is.False);}
  [Test]public void LinkHasExplicitDirectionAccessAndEnablePolicy(){var s=new EnvironmentState();var l=s.Link;Assert.That(l.Resolve(l.Source,TraversalAccess.Player,out var p,out var f));Assert.That(p,Is.EqualTo(l.Destination));Assert.That(f,Is.EqualTo(new Point2(1,0)));Assert.That(l.Resolve(l.Source,TraversalAccess.Enemy,out _,out _),Is.False);l.Bidirectional=false;Assert.That(l.Resolve(l.Destination,TraversalAccess.Player,out _,out _),Is.False);l.Enabled=false;Assert.That(l.Resolve(l.Source,TraversalAccess.Player,out _,out _),Is.False);l.Enabled=true;l.Unlocked=false;Assert.That(l.Resolve(l.Source,TraversalAccess.Player,out _,out _),Is.False);}
  [Test]public void ArrivalClearanceAndRevalidationAreMandatory(){var s=new EnvironmentState();var t=new EnvironmentTransfer();Assert.That(t.Begin(s.Link,s.Link.Source,TraversalAccess.Player,p=>false),Is.False);Assert.That(t.Begin(s.Link,s.Link.Source,TraversalAccess.Player,p=>Clear(s,p)));Assert.That(t.Commit(t.Ticket,true,p=>false,(p,f)=>Assert.Fail()),Is.False);Assert.That(t.Phase,Is.EqualTo(TransferPhase.Cancelled));Assert.That(t.Transfers,Is.Zero);}
  [Test]public void ExactlyOnceNeedsChunksReadyAndRejectsStaleTickets(){var s=new EnvironmentState();var t=new EnvironmentTransfer();int commits=0;Assert.That(t.Begin(s.Link,s.Link.Source,TraversalAccess.Player,p=>Clear(s,p)));int id=t.Ticket;Assert.That(t.Begin(s.Link,s.Link.Source,TraversalAccess.Player,p=>true),Is.False);Assert.That(t.Commit(id,false,p=>true,(p,f)=>commits++),Is.False);Assert.That(t.Commit(id,true,p=>true,(p,f)=>commits++));Assert.That(t.Commit(id,true,p=>true,(p,f)=>commits++),Is.False);Assert.That(commits,Is.EqualTo(1));}
  [Test]public void InterruptedPreparationCannotCommitLater(){var s=new EnvironmentState();var t=new EnvironmentTransfer();t.Begin(s.Link,s.Link.Source,TraversalAccess.Player,p=>true);int old=t.Ticket;t.Cancel();t.Begin(s.Link,s.Link.Source,TraversalAccess.Player,p=>true);Assert.That(t.Commit(old,true,p=>true,(p,f)=>Assert.Fail()),Is.False);Assert.That(t.Commit(t.Ticket,true,p=>true,(p,f)=>{}));}
  [Test]public void NonadjacentLinksDoNotChangeOrdinaryNavigation(){var s=new EnvironmentState();var nav=new LabNavigation(s.World,s.Region.Entry);var route=new List<Point2>();nav.Route(s.Link.Destination,1,route);Assert.That(route.Any(p=>LabNavigation.Distance(p,s.Link.Destination)<2),Is.False);for(int i=1;i<route.Count;i++)Assert.That(LabNavigation.Distance(route[i-1],route[i]),Is.LessThanOrEqualTo(1.001));}
  [Test]public void SaveLoadUsesIdentityAndSmallDeltasAndValidatesState(){var s=new EnvironmentState();Open(s);s.World.Excavate(s.Region.X-32,s.Region.Y+23);s.OnExcavation();s.Link.Enabled=false;s.Link.Bidirectional=false;s.Link.Unlocked=false;using(var stream=new MemoryStream()){s.Save(stream);Assert.That(stream.Length,Is.LessThan(200));stream.Position=0;var b=EnvironmentState.Load(stream);Assert.That(b.Discovered&&b.CoverOpened);Assert.That(b.Link.Enabled||b.Link.Bidirectional||b.Link.Unlocked,Is.False);Assert.That(b.World.EditCount,Is.EqualTo(2));Assert.That(b.World.IsSolid(506,510));}}
  [Test]public void InconsistentDiscoveryIsRejectedOnLoad(){var s=new EnvironmentState{Discovered=true};using(var stream=new MemoryStream()){s.Save(stream);stream.Position=0;Assert.Throws<InvalidDataException>(()=>EnvironmentState.Load(stream));}}
  [Test]public void EvictionReloadKeepsLandmarkAndDiscoveryWithoutChunkAuthority(){var s=new EnvironmentState();Open(s);using(var stream=new StreamingGeometry(s.World,384,true)){var map=new FocusProjection(s.Region.Entry,48,28,24,.25,.2,1.9,new Point2(0,0));stream.Select(map,87,49,2.15);for(int i=0;i<300;i++)stream.Pump(20,100);int before=stream.TotalBuilt;stream.Select(new FocusProjection(s.Link.Destination,48,28,24,.25,.2,1.9,new Point2(0,0)),87,49,2.15);for(int i=0;i<300;i++){stream.Select(new FocusProjection(s.Link.Destination,48,28,24,.25,.2,1.9,new Point2(0,0)),87,49,2.15);stream.Pump(20,100);}stream.Select(map,87,49,2.15);for(int i=0;i<300;i++){stream.Select(map,87,49,2.15);stream.Pump(20,100);}Assert.That(stream.TotalEvicted,Is.GreaterThan(0));Assert.That(stream.TotalBuilt,Is.GreaterThan(before));Assert.That(s.Discovered);Assert.That(s.World.IsSolid(506,510));Assert.That(s.World.IsSolid(544,494),Is.False);}}
  [Test]public void LargeActorRoutesAroundProtectedSpineAndUnderCover()
  {
   var s=new EnvironmentState();var path=new List<Point2>();var target=s.Region.P(19,0);var nav=new LabNavigation(s.World,s.Region.Entry);Assert.That(nav.Route(target,7,path));Assert.That(LabNavigation.Distance(path[0],target),Is.LessThan(1));foreach(var q in path)Assert.That(Clear(s,q,7));Assert.That(path.Any(q=>q.Y<s.Region.Y-9||q.Y>s.Region.Y+5));var roof=new LabNavigation(s.World,s.Region.P(-18,23));roof.Route(s.Region.P(-8,23),7,path);foreach(var q in path)Assert.That(Clear(s,q,7));Assert.That(path.Count,Is.GreaterThan(5));
  }
  [Test]public void AuthoredFixtureCannotBeSilentlyWrittenAsLegacyWorld(){var s=new EnvironmentState();using(var stream=new MemoryStream())Assert.Throws<InvalidOperationException>(()=>s.World.Save(stream));}
  [Test]public void RevealedRoomCanBeVisibleFromItsEntranceWithoutPlayerInside(){var s=new EnvironmentState();Open(s);Assert.That(s.CurrentlyVisible(s.Region.P(29,-18)));Assert.That(s.Region.InRoom(s.Region.P(29,-18)),Is.False);}
  [Test]public void ActualHostPreparesCameraBeforeTransferAndKeepsRepeatedResourcesBounded()
  {
   SporeGobbo.Geometry.Preview.Editor.Stage51Tools.Install();try
   {
    var env=UnityEngine.Object.FindAnyObjectByType<Stage51Preview>();env.Initialize();var host=env.Live;var mask=env.GetComponentsInChildren<MeshRenderer>().Single(m=>m.name=="Stage51 batch 3");var block=new MaterialPropertyBlock();mask.GetPropertyBlock(block);Assert.That(Vector4.Distance((Vector4)block.GetColor("_Color"),(Vector4)host.materials[(int)PreviewLayer.Solid].GetColor("_Color")),Is.LessThan(.00001f));env.Lab.encounterCount=0;env.Go(r=>r.P(-35,3));for(int i=0;i<1200&&!host.Ready;i++)host.Refresh(0);Assert.That(host.Ready);var source=host.Position;Assert.That(env.BeginTravel());Assert.That(host.Position,Is.EqualTo(source));env.CancelTravel();Assert.That(host.Position,Is.EqualTo(source));
    for(int n=0;n<4;n++){Assert.That(env.BeginTravel());int frames=0;while(env.Loading&&frames++<1600){host.Refresh(0);env.Present();}Assert.That(env.Loading,Is.False);Assert.That(env.Transfer.Transfers,Is.EqualTo(n+1));Assert.That(host.Ready);Assert.That(host.Snapshot.Focus.Y,Is.EqualTo(host.Position.y).Within(.0001));Assert.That(host.Stream.Resident.Count,Is.LessThanOrEqualTo(384));Assert.That(env.GetComponentsInChildren<MeshFilter>().Count(f=>f.name.StartsWith("Stage51 batch")),Is.EqualTo(7));}
    for(int n=0;n<3;n++){env.ResetDemo();Assert.That(env.OwnedMeshes,Is.EqualTo(7));Assert.That(env.Lab.OwnedMeshes,Is.EqualTo(46));}
   }finally{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);}
  }
 }
}
